<template>
  <section class="agent-workspace" aria-labelledby="agent-design-title">
    <header class="agent-workspace__header">
      <div><p class="section-index">协作式设计</p><h2 id="agent-design-title">文创 Agent 工作区</h2><p>每个对话独立保存需求、设计状态与上下文；图片将在方案确认后开放。</p></div>
      <button type="button" class="secondary-button" @click="$emit('return-to-history')">协作式历史记录</button>
    </header>
    <p v-if="errorBySessionId[currentSessionId]" class="agent-error" role="alert">{{ errorBySessionId[currentSessionId] }}</p>

    <div class="agent-workspace__grid">
      <aside class="session-rail" aria-label="设计对话列表">
        <button type="button" class="new-session" :disabled="creating" @click="create"><span>＋</span> 新建对话</button>
        <p v-if="sessionsLoading" class="rail-note">正在读取对话…</p>
        <nav v-else-if="displaySessions.length" class="session-list">
          <button v-for="item in displaySessions" :key="item.session_id" type="button" :class="['session-item', { active: item.session_id === currentSessionId || item.isLocalDraft }]" @click="item.isLocalDraft ? create() : select(item.session_id)">
            <span class="session-item__title">{{ item.title }}</span><small>{{ statusLabel(item.status) }} · {{ formatShortDate(item.updated_at) }}</small>
            <i v-if="item.has_pending_action" aria-label="有待确认事项">●</i><i v-else-if="pendingBySessionId[item.session_id]" class="session-item__busy" aria-label="正在处理">●</i>
          </button>
        </nav>
        <div v-else class="session-list-empty"><strong>还没有对话</strong><span>从一个新的文创构思开始</span></div>
      </aside>

      <main class="conversation-stage" aria-live="polite">
        <div v-if="sessionLoadingById[currentSessionId] && !currentSession" class="empty-state">正在打开这个设计对话…</div>
        <template v-else-if="currentSession || isNewDraft">
          <header class="conversation-stage__header"><div><p class="section-index">当前对话</p><h3>{{ currentTitle }}</h3></div><span :class="['state-pill', currentSession?.status || 'draft']">{{ statusLabel(currentSession?.status || 'draft') }}</span></header>
          <section class="message-list" aria-label="消息历史">
            <article v-for="message in currentMessages" :key="message.id" :class="['message', message.role]">
              <span class="message__speaker">{{ message.role === 'user' ? '你' : '设计助手' }}</span>
              <template v-if="message.structured_output"><OutputCard :output="message.structured_output" @confirm="confirmAction" /></template>
              <p v-else-if="message.role === 'assistant' && message.message_type === 'runtime_result'">本轮智能协作未能生成有效回复，请重新尝试。</p>
              <p v-else>{{ message.text }}</p><time>{{ formatTime(message.created_at) }}</time>
            </article>
            <div v-if="pendingBySessionId[draftKey]" class="agent-thinking"><span></span>Agent 正在分析当前会话…</div>
            <p v-if="!currentMessages.length" class="empty-state">从一句产品需求开始，让这份设计慢慢成形。</p>
          </section>
          <section v-if="runtimeBySessionId[currentSessionId]" class="turn-meta">
            <span v-for="name in runtimeBySessionId[currentSessionId].safe_tool_events || []" :key="name">{{ toolLabel(name) }}</span>
          </section>
          <form class="agent-composer" @submit.prevent="send">
            <textarea v-model="draftBySessionId[draftKey]" rows="4" :disabled="Boolean(pendingBySessionId[draftKey])" placeholder="继续补充产品、场景、风格或希望避免的方向…"></textarea>
            <div><small>纯文本协作，不会在此页面生成图片。</small><button type="submit" class="primary-button" :disabled="!currentDraft.trim() || Boolean(pendingBySessionId[draftKey])">发送</button></div>
          </form>
        </template>
        <div v-else class="empty-state"><button type="button" class="primary-button" @click="create">开始新的文创对话</button></div>
      </main>

      <aside class="design-state" aria-label="当前设计状态">
        <template v-if="currentSession"><p class="section-index">设计状态</p><h3>当前会话速览</h3>
          <StateGroup title="当前目标" :items="[currentSession.brief_summary?.cultural_theme || currentSession.brief_summary?.product_type || '等待你提出第一个设计目标']" />
          <StateGroup title="已确认约束" tone="confirmed" :items="currentSession.brief_summary?.design_constraints || []" />
          <StateGroup title="暂定偏好" tone="tentative" :items="currentSession.brief_summary?.assumptions || []" />
          <StateGroup title="当前 Brief" :items="briefItems" />
          <StateGroup title="未解决问题" :items="unresolvedItems" />
          <section class="state-group"><h4>文化资料</h4><p>{{ ragLabel }}</p><small v-if="skillItems.length">已加载：{{ skillItems.join('、') }}</small></section>
          <section class="state-group context-state"><h4>上下文</h4><p>{{ contextCopy }}</p><small v-if="context.summary_version">摘要版本 {{ context.summary_version }} · 保留最近 {{ context.recent_messages_included || 0 }} 条</small></section>
          <section class="state-group"><h4>图片</h4><p>将在方案确认后开放</p></section>
        </template>
        <p v-else class="rail-note">选择一个对话后查看其独立设计状态。</p>
      </aside>
    </div>
  </section>
</template>

<script>
import { createClientId } from '../utils/clientId'
import { createSession, getSession, listSessions, runAssistantTurn, submitDecision } from '../services/agentDialogueApi'

const StateGroup = { props: { title: String, items: { type: Array, default: () => [] }, tone: String }, template: '<section class="state-group"><h4>{{ title }}</h4><ul v-if="items.length" :class="tone"><li v-for="item in items" :key="item">{{ item }}</li></ul><p v-else>暂无</p></section>' }
const OutputCard = {
  props: { output: { type: Object, required: true } }, emits: ['confirm'],
  computed: { result() { return this.output.result || this.output }, kind() { return this.result?.kind || 'direct_answer' }, briefRows() { const b = this.result?.brief || {}; return [['设计目标', b.design_goal || b.goal], ['产品类型', b.product_type], ['受众', b.target_audience], ['风格', b.style], ['材质／工艺', b.materials || b.material]] } },
  template: `<section :class="['output-card', kind]"><template v-if="kind === 'ask_user'"><strong>需要你补充</strong><h4>{{ result.question }}</h4><p>{{ result.reason_summary || '当前资料不足，需要你补充后继续。' }}</p></template><template v-else-if="kind === 'propose_brief'"><strong>候选 Brief</strong><dl><div v-for="row in briefRows" :key="row[0]" v-if="row[1]"><dt>{{ row[0] }}</dt><dd>{{ row[1] }}</dd></div></dl><p>{{ result.summary }}</p><small v-if="result.evidence_source_ids?.length">文化证据：{{ result.evidence_source_ids.join('、') }}</small><small v-if="result.used_skill_ids?.length">设计方法：{{ result.used_skill_ids.join('、') }}</small></template><template v-else-if="kind === 'propose_design_revision'"><strong>设计修订建议</strong><p>{{ result.summary || result.reason }}</p><p v-if="result.affected_constraints?.length">涉及约束：{{ result.affected_constraints.join('、') }}</p></template><template v-else-if="kind === 'request_business_action'"><strong>需要确认的业务动作</strong><h4>{{ result.action_name }}</h4><p>{{ result.impact || result.reason_summary }}</p><button type="button" class="secondary-button" @click="$emit('confirm', result)">确认前继续讨论</button></template><template v-else><p>{{ result.answer || result.summary || '设计助手已整理当前建议。' }}</p></template></section>`,
}

export default {
  name: 'AgentDesignPanel', components: { StateGroup, OutputCard }, emits: ['return-to-history'],
  data: () => ({ sessions: [], sessionsById: {}, messagesBySessionId: {}, runtimeBySessionId: {}, draftBySessionId: {}, pendingBySessionId: {}, sessionLoadingById: {}, errorBySessionId: {}, currentSessionId: '', isNewDraft: false, sessionsLoading: false, creating: false }),
  computed: {
    displaySessions() { return this.isNewDraft ? [{ session_id: '__local_draft__', isLocalDraft: true, title: '新建对话', status: 'draft', updated_at: '', has_pending_action: false }, ...this.sessions] : this.sessions },
    draftKey() { return this.currentSessionId || '__new_draft__' }, currentSession() { return this.sessionsById[this.currentSessionId] || null }, currentMessages() { return this.messagesBySessionId[this.currentSessionId] || [] }, currentDraft() { return this.draftBySessionId[this.draftKey] || '' }, currentTitle() { return this.sessions.find((item) => item.session_id === this.currentSessionId)?.title || this.currentSession?.brief_summary?.product_type || (this.isNewDraft ? '新对话' : '文创设计对话') },
    context() { return this.runtimeBySessionId[this.currentSessionId]?.context_metadata || {} }, contextCopy() { return this.context.compression_triggered ? '已整理较早的对话历史，关键目标和约束仍被保留' : '当前会话上下文正常' },
    briefItems() { const b = this.currentSession?.brief_summary; return b ? [b.product_type, b.use_case, b.style].filter(Boolean) : [] }, unresolvedItems() { const last = [...this.currentMessages].reverse().find((item) => item.structured_output?.result?.kind === 'ask_user'); return last ? (last.structured_output.result.missing_fields || ['等待你的补充']) : [] },
    skillItems() { return this.currentMessages.flatMap((item) => item.structured_output?.result?.used_skill_ids || []) }, ragLabel() { const output = [...this.currentMessages].reverse().find((item) => item.structured_output)?.structured_output?.result || {}; return output.evidence_source_ids?.length ? '找到可引用的文化资料' : (output.kind === 'ask_user' ? '需要补充主题、产品或场景' : '当前文库没有可靠匹配，可按纯创意方向继续') },
  },
  async mounted() { window.addEventListener('popstate', this.restoreFromUrl); await this.loadSessions(); await this.restoreFromUrl() }, beforeUnmount() { window.removeEventListener('popstate', this.restoreFromUrl) },
  methods: {
    async loadSessions() { this.sessionsLoading = true; try { this.sessions = await listSessions() } catch (error) { this.errorBySessionId[this.currentSessionId] = this.errorText(error) } finally { this.sessionsLoading = false } },
    setUrl(id) { const url = new URL(window.location.href); if (id) url.searchParams.set('agent_session_id', id); else url.searchParams.delete('agent_session_id'); window.history.pushState({}, '', url) },
    async restoreFromUrl() { const id = new URLSearchParams(window.location.search).get('agent_session_id') || localStorage.getItem('agent_workspace_session'); if (id) await this.select(id, false) },
    async create() { if (this.isNewDraft) return; this.isNewDraft = true; this.currentSessionId = ''; if (!(this.draftBySessionId.__new_draft__ || '').trim()) this.draftBySessionId.__new_draft__ = ''; this.setUrl(null) },
    async select(id, changeUrl = true) { if (changeUrl) this.setUrl(id); this.isNewDraft = false; this.currentSessionId = id; localStorage.setItem('agent_workspace_session', id); if (!this.sessionsById[id]) await this.loadSession(id); },
    async loadSession(id) { this.sessionLoadingById[id] = true; this.errorBySessionId[id] = ''; try { const session = await getSession(id); this.sessionsById[id] = session; this.messagesBySessionId[id] = session.messages || []; if (!this.sessions.some((item) => item.session_id === id)) await this.loadSessions() } catch (error) { this.errorBySessionId[id] = error?.response?.status === 404 ? '这个对话不存在或你无权访问。' : this.errorText(error) } finally { this.sessionLoadingById[id] = false } },
    async send() { let id = this.currentSessionId; const key = this.draftKey; const text = this.currentDraft.trim(); if (!text || this.pendingBySessionId[key] || this.creating) return; const pending = this.pendingBySessionId[key] || { clientTurnId: createClientId(), text }; this.pendingBySessionId[key] = pending; this.errorBySessionId[key] = ''; try { if (!id) { this.creating = true; const session = await createSession(); id = session.session_id; this.currentSessionId = id; this.isNewDraft = false; this.sessionsById[id] = session; this.messagesBySessionId[id] = session.messages || []; this.draftBySessionId[id] = text; this.setUrl(id); localStorage.setItem('agent_workspace_session', id); delete this.pendingBySessionId[key]; this.pendingBySessionId[id] = pending } const response = await runAssistantTurn(id, text, pending.clientTurnId); this.runtimeBySessionId[id] = response.data.display; this.draftBySessionId[id] = ''; delete this.pendingBySessionId[id]; await this.loadSession(id); await this.loadSessions() } catch (error) { this.errorBySessionId[id || key] = this.errorText(error); this.draftBySessionId[id || key] = text } finally { this.creating = false } },
    async confirmAction(result) { if (!result?.decision || !this.currentSession) return; try { await submitDecision(this.currentSessionId, result.decision, this.currentSession.status, this.currentSession.version); await this.loadSession(this.currentSessionId) } catch (error) { this.errorBySessionId[this.currentSessionId] = this.errorText(error) } },
    statusLabel(value) { return ({ draft: '尚未开始', created: '待开始', extracting_brief: '整理需求', waiting_brief_confirmation: '待确认', waiting_text_feedback: '可继续调整', completed: '已完成' })[value] || '协作中' }, toolLabel(name) { return ({ inspect_design_state: '已读取当前设计状态', search_cultural_knowledge: '已查询文化资料', load_design_skill: '已加载设计方法', validate_design_constraints: '已检查设计约束' })[name] || '已完成安全检查' },
    formatShortDate(value) { const d = new Date(value); return Number.isNaN(d.getTime()) ? '刚刚' : d.toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' }) }, formatTime(value) { const d = new Date(value); return Number.isNaN(d.getTime()) ? '' : d.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }, errorText(error) { return error?.response?.status === 404 ? '这个对话不存在或你无权访问。' : error?.kind === 'network' ? '无法连接协作服务，请稍后使用原 client_turn_id 重试。' : (error?.message || '协作服务暂时不可用。') },
  },
}
</script>

<style scoped>
.agent-workspace{margin-top:1.25rem}.agent-workspace__header{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;padding-bottom:1rem;border-bottom:1px solid #d4cec2}.agent-workspace h2{margin:.2rem 0;color:#245244;font-size:clamp(1.5rem,3vw,2.2rem)}.agent-workspace h3{margin:.1rem 0;color:#245244}.agent-workspace__header p{margin:.25rem 0;color:#59655b;line-height:1.6}.agent-workspace__grid{display:grid;grid-template-columns:220px minmax(0,1fr) 260px;gap:1rem;margin-top:1rem;height:clamp(640px,calc(100dvh - 255px),820px);min-height:0;max-height:calc(100dvh - 180px);align-items:stretch;overflow:hidden}.session-rail,.conversation-stage,.design-state{min-width:0;min-height:0}.session-rail{display:flex;flex-direction:column;overflow:hidden;background:#f4f1e8;border:1px solid #d8d0c0;padding:.8rem}.new-session{flex:0 0 auto;width:100%;border:1px dashed #245244;background:#edf3ed;color:#245244;padding:.7rem;font:inherit;font-weight:700}.new-session span{font-size:1.15rem}.session-list{display:grid;gap:.35rem;flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;margin-top:.75rem;padding-right:.2rem}.session-list-empty{padding:1rem .25rem;color:#697468;display:grid;gap:.25rem}.session-list-empty span{font-size:.82rem}.session-item{position:relative;min-height:68px;box-sizing:border-box;text-align:left;border:0;border-left:3px solid transparent;background:transparent;padding:.6rem .55rem;color:#405046;font:inherit}.session-item:hover,.session-item.active{background:#fffdf5;border-left-color:#b56d3c}.session-item__title{display:-webkit-box;font-weight:650;line-height:1.35;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical}.session-item small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#718075;margin-top:.28rem}.session-item i{position:absolute;right:.45rem;top:.6rem;color:#b56d3c;font-style:normal;font-size:.65rem}.session-item__busy{color:#245244!important;animation:pulse 1.2s infinite}.conversation-stage{border:1px solid #d4cec2;background:#fffdf7;display:flex;flex-direction:column;overflow:hidden}.conversation-stage__header{flex:0 0 auto;display:flex;justify-content:space-between;align-items:flex-start;padding:1rem 1rem .75rem;border-bottom:1px solid #e4ddd0}.state-pill{font-size:.76rem;padding:.25rem .45rem;background:#edf3ed;color:#245244}.message-list{display:grid;gap:.85rem;align-content:start;flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:1rem}.message{max-width:88%;overflow-wrap:anywhere;padding:.75rem .9rem;background:#fff;border:1px solid #e0d9cd}.message.user{justify-self:end;background:#e9f1ec;border-color:#b9cfbf}.message__speaker{font-size:.75rem;color:#6b776d;font-weight:700}.message p{white-space:pre-wrap;line-height:1.65;margin:.3rem 0}.message time{font-size:.72rem;color:#879086}.agent-thinking{color:#5a695d;font-size:.9rem}.agent-thinking span{display:inline-block;width:.55rem;height:.55rem;border-radius:50%;background:#b56d3c;margin-right:.45rem;animation:pulse 1s infinite}.agent-composer{flex:0 0 auto;margin-top:auto;border-top:1px solid #e4ddd0;padding:.8rem;display:grid;gap:.5rem}.agent-composer textarea{width:100%;min-height:112px;max-height:160px;box-sizing:border-box;border:1px solid #bfc7b9;background:#fff;padding:.65rem;font:inherit;resize:vertical}.agent-composer div{display:flex;justify-content:space-between;align-items:center;gap:.75rem}.agent-composer small{color:#697468}.design-state{overflow-y:auto;overscroll-behavior:contain;background:#f4f1e8;border:1px solid #d8d0c0;padding:.8rem}.design-state h3{margin-bottom:.85rem}.state-group{border-top:1px solid #d8d0c0;padding:.65rem 0}.state-group h4{margin:0 0 .3rem;color:#245244;font-size:.85rem}.state-group p,.state-group li,.state-group small{font-size:.82rem;line-height:1.55;color:#59655b}.state-group p{margin:0}.state-group ul{margin:.15rem 0;padding-left:1rem}.state-group .confirmed li::marker{color:#245244}.state-group .tentative li::marker{color:#b56d3c}.output-card{margin-top:.45rem;border-left:3px solid #245244;background:#f6f8f2;padding:.7rem}.output-card.ask_user{border-color:#b56d3c;background:#fff7ee}.output-card h4{margin:.35rem 0;color:#245244}.output-card p{margin:.3rem 0}.output-card small{display:block;color:#677067;margin-top:.25rem}.output-card dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.35rem;margin:.5rem 0}.output-card dt{font-size:.72rem;color:#697468}.output-card dd{margin:.08rem 0;font-size:.84rem}.turn-meta{flex:0 0 auto;display:flex;flex-wrap:wrap;gap:.35rem;padding:0 1rem .75rem}.turn-meta span{font-size:.75rem;background:#edf3ed;color:#245244;padding:.25rem .45rem}.empty-state,.rail-note{color:#697468;padding:1rem;text-align:center}.agent-error{padding:.7rem;background:#fff0ea;border-left:3px solid #b74b3c}@keyframes pulse{50%{opacity:.35}}@media(max-width:980px){.agent-workspace__grid{height:auto;max-height:none;grid-template-columns:190px minmax(0,1fr)}.design-state{grid-column:1/-1;max-height:280px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.7rem}.design-state>.section-index,.design-state>h3{grid-column:1/-1}.state-group{border-top:0;border-left:1px solid #d8d0c0;padding-left:.65rem}}@media(max-width:680px){.agent-workspace__header{display:grid}.agent-workspace__grid{grid-template-columns:1fr;height:auto;max-height:none}.session-rail{max-height:190px}.conversation-stage{min-height:620px}.design-state{display:block;max-height:none}.state-group{border-top:1px solid #d8d0c0;border-left:0;padding-left:0}.message{max-width:96%}}
/* Let the document own conversation scrolling; the bounded rail is the only internal scroller. */
.agent-workspace{max-width:1520px;margin-left:auto;margin-right:auto;padding:0 1rem}.agent-workspace__grid{height:auto;max-height:none;min-height:640px;grid-template-columns:230px minmax(620px,1fr) 235px;align-items:start;overflow:visible}.session-rail{position:sticky;top:1rem;height:calc(100dvh - 2rem);max-height:calc(100dvh - 2rem);box-sizing:border-box}.session-list{flex:0 1 auto;max-height:calc(100dvh - 10rem);grid-auto-rows:auto;align-content:start}.session-item{flex:0 0 auto;min-height:76px;max-height:82px}.conversation-stage{display:block;overflow:visible;min-height:640px}.conversation-stage__header{position:sticky;top:0;z-index:3;background:#fffdf7}.message-list{overflow:visible;max-height:none;min-height:0;padding-bottom:11rem}.agent-composer{position:sticky;bottom:0;z-index:4;background:#fffdf7;box-shadow:0 -10px 18px rgba(40,55,43,.08)}.design-state{position:sticky;top:1rem;align-self:start;overflow:visible;max-height:none;padding:.7rem}.design-state h3{font-size:1rem;margin-bottom:.5rem}.state-group{padding:.45rem 0}.state-group p,.state-group li,.state-group small{font-size:.78rem}.session-list-empty{flex:0 0 auto}@media(max-width:1450px){.agent-workspace__grid{grid-template-columns:220px minmax(500px,1fr) 220px}}@media(max-width:1050px){.agent-workspace{padding:0}.agent-workspace__grid{grid-template-columns:205px minmax(0,1fr);min-height:600px}.design-state{position:static;grid-column:1/-1;display:block}.session-rail{position:static;height:auto;max-height:480px}.session-list{max-height:380px}.conversation-stage{min-height:600px}}@media(max-width:700px){.agent-workspace__grid{display:block}.session-rail{max-height:230px;margin-bottom:1rem}.conversation-stage{min-height:560px}.design-state{margin-top:1rem}.agent-workspace__header{padding-top:.25rem}}
</style>
